  "page.connType.rainbow.section-label.connection-type": "Connection Type",
  "page.connType.rainbow.h1.rainbow": "Rainbow",
  "page.connType.rainbow.p.yin-and-yang-companions-each-one": "Yin and Yang companions — each one brings out the other animal's true colors like a prism, hence the term \"Rainbow.\" A rare pairing worth cherishing whenever you come across it.",
  "page.connType.rainbow.p.totem-connections": "<a href=\"connections.html?v=20260807\">← Totem Connections</a>",
  "page.connType.rainbow.p.yin-and-yang-companions-each-one.2": "Yin and Yang companions — Each one brings out the other animal's true colors like a prism, hence the term \"Rainbow\" — with this type of connection, you really get to see each other shine! It's a rare pairing, and should be cherished whenever you come across it! It takes a lot of self-work before most people are ready for this type of connection — after all, the full spectrum of your true colors will be on display the entire time, so you'd better be sure you have all your facets polished and shiny!",
  "page.connType.rainbow.h3.other-connection-types": "Other connection types",
  "page.connType.rainbow.li.shadow": "<a href=\"connection-shadow.html?v=20260807\">Shadow</a>",
